counterexample:
/* base values referenced by foreign keys */
INSERT INTO t1 (c1, c2) VALUES
  ('X', 'anything');

INSERT INTO t2 (c1, c2) VALUES
  ('Corona', 'beer'),
  ('Amstel', 'beer');

