counterexample:
/* reference rows for the foreign-key targets */
INSERT INTO t1 (c1, c2) VALUES ('Beer1',  'x');   -- referenced by t5
INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'x');   -- drink code used in t5 & t6
INSERT INTO t3 (c1, c2) VALUES ('Other',  'x');   -- referenced by t6

/* row that makes Q1 true */
INSERT INTO t5 (c1, c2, c3) VALUES ('Beer1', 'Amstel', 3.00);

/* row that Q2 will project (note c1 <> 'Beer1') */
INSERT INTO t6 (c1, c2) VALUES ('Other', 'Amstel');

