counterexample:
/* referenced values for t1 and t2 */
INSERT INTO t1 (c1, c2) VALUES
  ('A',       'x'),
  ('Corona',  'virus'),
  ('Flu',     'virus');

INSERT INTO t2 (c1, c2) VALUES
  ('Corona',  'virus'),
  ('Flu',     'virus');

/* value referenced by t4 and t6 */
INSERT INTO t3 (c1, c2) VALUES ('A', 'something');

/* matching rows for the NATURAL JOIN (c1,c2,c3) */
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'Corona', 1);
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 1.00);

/* rows for t6: one Corona row (blocks Q1) and one non-Corona row (makes Q2 output) */
INSERT INTO t6 (c1, c2) VALUES ('A', 'Corona');
INSERT INTO t6 (c1, c2) VALUES ('A', 'Flu');

