  ('P1', 'Corona', 1);            -- referenced by t5, used by Q1

INSERT INTO t5 (c1, c2, c3) VALUES
  ('P1', 'Corona', 1.00);         -- identical (c1,c2,c3) -> joins with t4

/* t6 row with a DIFFERENT c2, so it does NOT cancel P1 in Q1
   and also does NOT join with t4 for Q2 */
INSERT INTO t6 (c1, c2) VALUES
  ('P1', 'Flu');

