/* referenced rows for t1 (needed by t4.c2 FK) */
INSERT INTO t1 (c1, c2) VALUES
  ('X1', 'x'),
  ('X2', 'x'),
  ('X3', 'x');

/* referenced rows for t3 (needed by t4.c1 FK) */
INSERT INTO t3 (c1, c2) VALUES
  ('A', 'y'),
  ('B', 'y');

/* rows for t4 that create the difference */
INSERT INTO t4 (c1, c2, c3) VALUES
  ('A', 'X1', 1),  -- sum for A starts
  ('A', 'X2', 2),  -- sum for A = 3
  ('B', 'X3', 3);  -- sum for B = 3 (equal), but no shared c3 value with A

