counterexample:
/* base tables referenced by FKs */
INSERT INTO t1 (c1, c2) VALUES ('X', 'tx');
INSERT INTO t2 (c1, c2) VALUES ('Y', 'ty');

/* two rows in t3:  one ("A") with no related row in t4, and one ("B") that is related */
