INSERT INTO t3 (c1, c2) VALUES ('B', 'tb');

/* a t4 row only for t3 = 'B' */
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'X', 10);

/* matching t5 row (needed for the join in Q2) */
INSERT INTO t5 (c1, c2, c3) VALUES ('X', 'Y', 1.23);

/* matching t6 row (needed for the join in Q2) */
INSERT INTO t6 (c1, c2) VALUES ('B', 'Y');

