counterexample:
-- owners / keys referenced by both tables
INSERT INTO t1 (c1, c2) VALUES
  ('x1', 'dummy'),
  ('BB', 'dummy'),   -- needed because t4.c2 references t1(c1)
  ('BC', 'dummy');

-- product key referenced by t5.c2
