counterexample:
/* t1: one product/whatever with key 'A' */
INSERT INTO t1 (c1, c2) VALUES ('A', 'foo');

/* t2: three different location/whatever keys */
INSERT INTO t2 (c1, c2) VALUES
  ('P', 'x'),
  ('Q', 'y'),
  ('R', 'z');

/* t3: one key that starts with 'B' */
INSERT INTO t3 (c1, c2) VALUES ('B1', 'anything');

/* t4: links the 'B%' key to t1.c1 = 'A' */
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'A', 1);

/* t5: three rows for the same c1 ('A') but different c2 values */
INSERT INTO t5 (c1, c2, c3) VALUES
  ('A', 'P', 10.00),
  ('A', 'Q', 12.00),
  ('A', 'R', 14.00);

