counterexample:
/* base rows referenced by foreign keys */
INSERT INTO t1 (c1, c2) VALUES
  ('A1','x'),
  ('A2','x'),
  ('A3','x');

INSERT INTO t2 (c1, c2) VALUES
  ('BeerX','lager');

