INSERT INTO t5 (c1, c2, c3) VALUES
  ('A1','BeerX',  5.00),   -- joins t4, kept by both queries
  ('A2','BeerX', 10.00),   -- joins t4, kept by both queries
  ('A3','BeerX', 20.00);   -- NO matching t4 row, kept only by Q1

