INSERT INTO t1 (c1, c2) VALUES ('B', 'b_data');

INSERT INTO t2 (c1, c2) VALUES ('x', 'x_data');
INSERT INTO t2 (c1, c2) VALUES ('y', 'y_data');
INSERT INTO t2 (c1, c2) VALUES ('z', 'z_data');

INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'x', 1.00);
