counterexample:
/* bars */
INSERT INTO t1 (c1, c2) VALUES
  ('bar1', 'dummy1'),
  ('bar2', 'dummy2');

/* drinkers */
INSERT INTO t3 (c1, c2) VALUES
  ('d1', 'x'),
  ('d2', 'y');

/* a single drink type so that t5 can reference t2 */
INSERT INTO t2 (c1, c2) VALUES
  ('drink1', 'z');

/* visits (drinker – bar – times) */
INSERT INTO t4 (c1, c2, c3) VALUES
  ('d1', 'bar1', 5),  -- max times for bar1
  ('d2', 'bar1', 3),  -- lower than max, triggers difference
  ('d1', 'bar2', 2);  -- some extra data, optional

/* prices recorded for the bars */
INSERT INTO t5 (c1, c2, c3) VALUES
  ('bar1', 'drink1', 4.50),
  ('bar2', 'drink1', 3.50);

